import React from 'react';

type ValidationResult = {
    title: string;
    regexName: string;
    passed: boolean;
    tags: string[];
};

const ResultsTable: React.FC<{ results: ValidationResult[] }> = ({ results }) => {
    return (
        <table className="results-table">
            <thead>
                <tr>
                    <th>Input Title</th>
                    <th>Regex Name</th>
                    <th>Pass/Fail</th>
                    <th>Generated Tags</th>
                </tr>
            </thead>
            <tbody>
                {results.map((result, index) => (
                    <tr key={index}>
                        <td>{result.title}</td>
                        <td>{result.regexName}</td>
                        <td>{result.passed ? 'Pass' : 'Fail'}</td>
                        <td>{result.tags.join(', ')}</td>
                    </tr>
                ))}
            </tbody>
        </table>
    );
};

export default ResultsTable;
